open(joinpath(dest,"FINDINGS.md"),"w") do io
 println(io,"# Species occupancy, partner breadth and local support\n")
 println(io,"Occupancy means number of sampled sites, not geographic range area. Degree is observed regional partner breadth: diet/host breadth for consumers, enemy/visitor breadth for resources. Degree-zero species are listed but excluded from specialist comparisons. Degree and occupancy both depend on observation effort.\n")
 for role in ["consumer","resource"]
  v=a[a.role.==role,:];t=DataFrame(sensitivity);t=t[(t.role.==role).&(t.maximum_degree.==2),:]
  println(io,@sprintf("- %s: positive degree–occupancy association in %d/10 datasets; median Spearman rho %.2f (range %.2f–%.2f).",role,count(v.rho_degree_occupancy.>0),median(v.rho_degree_occupancy),minimum(v.rho_degree_occupancy),maximum(v.rho_degree_occupancy)))
  println(io,@sprintf("  Species with <=2 partners are a majority in %d/10; median shares: %.1f%% of linked species, %.1f%% of regional links, %.1f%% of singleton links. Equal-dataset summaries; no pooling.",count(t.species_fraction.>.5),100median(t.species_fraction),100median(t.link_fraction),100median(t.singleton_share)))
 end
 println(io,"\n## Dataset results\n\n|Dataset|Consumer rho|Resource rho|K=1: one-site endpoint|K=1: one-site overlap only|K=1 despite C>1|\n|---|---:|---:|---:|---:|---:|")
 for ds in datasets
  v=o[(o.dataset.==ds).&(o.maximum_K.==1),:];ar=a[a.dataset.==ds,:]
  println(io,@sprintf("|%s|%.2f|%.2f|%.1f%%|%.1f%%|%.1f%%|",ds,ar.rho_degree_occupancy[1],ar.rho_degree_occupancy[2],100v.share_of_rare[1],100v.share_of_rare[2],100v.share_of_rare[3]))
 end
 println(io,"\n## Beyond opportunities\n")
 cv=td[(td.role.=="consumer").&(td.metric.=="low_degree_singleton_excess"),:]
 println(io,@sprintf("Consumers with <=2 partners have a smaller singleton-rate excess than the within-C null in %d/10 datasets (median difference %.1f percentage points). Thus opportunity restriction alone predicts a stronger specialist disadvantage than observed; the conditional pattern offsets rather than amplifies it. This is conditional on known interactions, not evidence that specialists intrinsically interact more efficiently.",count(cv.effect.<0),100median(cv.effect)))
 for role in ["consumer","resource"],metric in ["degree_K_rho","low_degree_singleton_excess"]
  v=td[(td.role.==role).&(td.metric.==metric),:];sig=v.dataset[v.adjusted_p.<.05]
  println(io,"- $role, $metric: ",length(sig),"/10 departures after BH correction across 40 comparisons. ",join(sig,", "),".")
 end
 println(io,"\nThe within-C permutation assigns observed K among links with identical C. It retains endpoint degrees, pair opportunities, total support, and the entire support distribution. It asks whether low-degree endpoints are associated with low support beyond these opportunities; it cannot explain or predict the distribution itself. Null bands are central 95% allocation-reference intervals, not confidence intervals. A departure does not isolate a causal diet effect. Shared species make links dependent; permutation results are conditional diagnostics under exchangeability within C, not independent-link population tests.\n")
 println(io,"## Interpretation\n\nRestricted occupancy necessarily bounds support: K<=C<=min(endpoint occupancies). A one-site endpoint forces every one of its observed links to be a singleton. But numerous specialist species need not generate most links: each has few partners, so species fractions must be compared with link fractions. The decomposition measures which rare links are forced to be rare by limited opportunities; it is not a causal attribution. K=1 despite C>1 requires something beyond one-site opportunity restriction, potentially unequal encounters, partner compatibility, local context or imperfect detection. It does not identify which. Thresholds K<=2 and K<=3 show whether the result extends beyond singletons. Degree thresholds 1,2,3 are sensitivity descriptions, not universal specialist definitions. Partial rank correlations are descriptive only and do not establish mediation.\n")
 println(io,"## Provenance and limitations\n\nConfirmed restored occurrence records and existing validated interaction records are used. Every K and C was reconstructed and checked; the site universe and prior input hashes were verified. Original input hashes and current source hashes accompany the outputs. Confirmed restorations are retained. Unconfirmed Gottin_PP missing-identity records, Garraf_PP2 zero columns and Montseny zero row remain excluded. Garraf_HP/Olot historical one-link discrepancies remain unresolved. Many species presences originate from interaction sampling, so occupancy–degree associations can include observation coupling. Gottin datasets share sites; Catalan datasets have collection overlap limitations (see copied metadata tables). No independent landscape replication is claimed. Binary records cannot separate ecological absence from nondetection, and spatial occupancy is not habitat specialism. No new gap predictions or ecological mechanisms are fitted.\n")
end
